function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
let products=read('wk-products',seed),cart=read('wk-cart',{}),orders=read('wk-orders',[]),category='All',filter='all',admin=false,delivery=read('wk-location',{area:'Wakad, Pune',pin:'411057'});
const money=v=>'₹'+Number(v).toLocaleString('en-IN');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){localStorage.setItem('wk-products',JSON.stringify(products));localStorage.setItem('wk-cart',JSON.stringify(cart));localStorage.setItem('wk-orders',JSON.stringify(orders))}
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function art(p){return p.pack?`<div class="pack" style="background:${p.color};color:${p.white?'white':'#345131'}"><small>${escape(p.sub)}</small>${escape(p.pack)}<span class="packicon">${escape(p.emoji)}</span><small>${escape(p.unit)}</small></div>`:`<span class="emoji">${escape(p.emoji)}</span>`}
function qty(p){return cart[p.id]?`<div class="qty"><button data-change="${p.id}" data-n="-1" aria-label="Remove one ${escape(p.name)}">−</button><b>${cart[p.id]}</b><button data-change="${p.id}" data-n="1" aria-label="Add one ${escape(p.name)}">+</button></div>`:`<button class="add" data-change="${p.id}" data-n="1" ${p.stock<1?'disabled':''}>${p.stock<1?'SOLD OUT':'ADD +'}</button>`}
function render(){let list=products.filter(p=>(category==='All'||cats[p.cat][0]===category)&&p.name.toLowerCase().includes($('#search').value.toLowerCase())&&(filter!=='deals'||p.mrp>p.price)&&(filter!=='stock'||p.stock>0));if($('#sort').value==='low')list.sort((a,b)=>a.price-b.price);if($('#sort').value==='high')list.sort((a,b)=>b.price-a.price);$('#producttitle').textContent=category==='All'?'Fresh picks for your basket':category;$('#resultcount').textContent=list.length+' products';$('#products').innerHTML=list.length?list.map(p=>`<article class="product-card"><div class="product-image">${p.mrp>p.price?`<span class="discount">${Math.round((1-p.price/p.mrp)*100)}% OFF</span>`:''}${art(p)}</div><span class="time">◷ 25–35 MINS</span><h3>${escape(p.name)}</h3><div class="unit">${escape(p.unit)}</div><div class="product-bottom"><div class="price">${money(p.price)}${p.mrp>p.price?`<del>${money(p.mrp)}</del>`:''}</div>${qty(p)}</div></article>`).join(''):'<div class="empty">No products found. Try another search or category.</div>';let count=Object.values(cart).reduce((a,b)=>a+b,0);$('#count').textContent=count;$('#cartlabel').textContent=count?money(total()):'My cart';$$('[data-cat]').forEach(b=>b.classList.toggle('active',b.dataset.cat===category));}
function total(){return products.reduce((s,p)=>s+p.price*(cart[p.id]||0),0)}
function change(id,n){let p=products.find(p=>p.id===id);if((cart[id]||0)+n>p.stock)return notify('Only '+p.stock+' available in stock');cart[id]=Math.max(0,(cart[id]||0)+n);if(!cart[id])delete cart[id];persist();render();if(!$('#drawer').hidden)drawCart()}
$('#categories').innerHTML=cats.map(([name,emoji,color])=>`<button class="category-card" data-cat="${name}"><div class="category-picture" style="background:${color}"><span>${emoji}</span></div><b>${name==='All'?'Shop all essentials':name}</b></button>`).join('');
document.addEventListener('click',e=>{let c=e.target.closest('[data-cat]');if(c){category=c.dataset.cat;render();$('#products-section').scrollIntoView({behavior:'smooth',block:'start'})}let b=e.target.closest('[data-change]');if(b)change(Number(b.dataset.change),Number(b.dataset.n));let f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===f));render()}});
$('#search').addEventListener('input',()=>{if(admin)toggleAdmin();render()});$('#sort').onchange=render;$('#shopnow').onclick=()=>$('#products-section').scrollIntoView({behavior:'smooth'});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}if(e.key==='Escape')closeCart()});
function closeCart(){$('#drawer').hidden=true;$('#overlay').hidden=true;document.body.style.overflow=''}
function drawCart(){let items=products.filter(p=>cart[p.id]);$('#drawer').innerHTML=`<div class="drawer-head"><h2>Your basket <span>(${Object.values(cart).reduce((a,b)=>a+b,0)})</span></h2><button class="close" id="closecart" aria-label="Close cart">×</button></div><p style="font-size:11px">From Wakad Circle, with care · 25–35 mins</p>${items.length?items.map(p=>`<div class="cart-item"><span>${escape(p.emoji)}</span><div><b>${escape(p.name)}</b><small>${escape(p.unit)} · ${money(p.price)}</small>${qty(p)}</div><b>${money(p.price*cart[p.id])}</b></div>`).join('')+`<div class="bill"><b>Bill details</b><p>Item total <span>${money(total())}</span></p><p>Delivery <span>${total()>=499?'FREE':money(25)}</span></p><p>To pay <span>${money(total()+(total()>=499?0:25))}</span></p></div>${total()<499?`<p class="form-note">Add ${money(499-total())} more for free delivery.</p>`:''}<button id="checkout" class="primary wide">Proceed to checkout →</button><p class="form-note">${window.WK_FIREBASE_CONFIG?'Cash on delivery · Sign in with your phone to order.':'Demo checkout · Cash on delivery · Orders saved in this browser.'}</p>`:'<div class="empty"><div style="font-size:60px">🧺</div><h2>A little empty in here.</h2><p>Your daily essentials are waiting.</p><button class="primary" id="continue">Start shopping</button></div>'}`;$('#closecart').onclick=closeCart;if($('#continue'))$('#continue').onclick=closeCart;if($('#checkout'))$('#checkout').onclick=checkout}
$('#cartbtn').onclick=()=>{$('#drawer').hidden=false;$('#overlay').hidden=false;document.body.style.overflow='hidden';drawCart();$('#closecart').focus()};$('#overlay').onclick=closeCart;
function showModal(html){$('#modal').innerHTML=`<button class="close" style="float:right" data-close-dialog aria-label="Close dialog">×</button>${html}`;$('#modal').showModal()}
function checkout(){if(window.WK_FIREBASE_CONFIG&&!window.WKCloud)return notify('Firebase is not connected yet.');if(window.WKCloud&&!window.WKCloud.user)return window.WK.login(checkout);showModal(`<h2>A few delivery details.</h2><p class="form-note">${window.WK_FIREBASE_CONFIG?'Pay cash on delivery. Your order will be sent to the shop.':'Demo order · No payment is collected.'}</p><form id="checkoutform"><label>Your name<input name="name" required maxlength="80" placeholder="Full name"></label><label>Mobile number<input name="phone" required pattern="[6-9][0-9]{9}" inputmode="tel" placeholder="10-digit mobile number"></label><label>Delivery address<textarea name="address" required minlength="10" maxlength="300" placeholder="Flat, building, street, Wakad"></textarea></label><label>PIN code<input name="pin" required pattern="411057" value="${escape(delivery.pin)}" title="Delivery is currently available in 411057"></label><button class="primary wide">${window.WK_FIREBASE_CONFIG?'Place order':'Place demo order'} · ${money(total()+(total()>=499?0:25))}</button></form>`);$('#checkoutform').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));if(window.WKCloud)return window.WK.submitCloudOrder(data,e.target);for(let p of products)if((cart[p.id]||0)>p.stock)return notify(p.name+' has insufficient stock');let order={id:'WK'+Date.now().toString().slice(-7),date:new Date().toLocaleString('en-IN'),...data,total:total()+(total()>=499?0:25),items:products.filter(p=>cart[p.id]).map(p=>({name:p.name,qty:cart[p.id],price:p.price})),status:'New'};orders.unshift(order);products.forEach(p=>p.stock-=cart[p.id]||0);cart={};persist();render();closeCart();showModal(`<div style="text-align:center;padding:20px 0"><div style="font-size:55px;color:var(--green)">✓</div><h2>Your demo order is in!</h2><p>Order ${order.id} · ${money(order.total)}</p><p class="form-note">You can view and update this order in Manage shop.<br>This is a browser demo; no store has been notified.</p><button class="primary" data-close-dialog>Keep shopping</button></div>`)}}
function toggleAdmin(){if(!admin&&window.WK_FIREBASE_CONFIG&&(!window.WKCloud||!window.WKCloud.owner)){if(!window.WKCloud?.user)return window.WK.login(toggleAdmin);return notify('This account is not registered as the shopkeeper.')}admin=!admin;$('#admin').hidden=!admin;$('#store').hidden=admin;$('#nav').hidden=admin;$('#manage').innerHTML=admin?'↗ <span>View storefront</span>':'▦ <span>Manage shop</span>';if(admin)renderAdmin();window.scrollTo({top:0,behavior:'smooth'})}$('#manage').onclick=toggleAdmin;
function renderAdmin(){$('#stats').innerHTML=[['Products on shelf',products.length],['Low stock · below 10',products.filter(p=>p.stock<10).length],[window.WK_FIREBASE_CONFIG?'Orders':'Demo orders',orders.length],['Order value',money(orders.reduce((s,o)=>s+o.total,0))]].map(([a,b])=>`<div class="stat"><small>${a}</small><b>${b}</b></div>`).join('');$('#inventory').innerHTML=`<div class="demo-note">${window.WK_FIREBASE_CONFIG?'Shared Firebase inventory · Shopkeeper account required':'Presentation demo · Try changing a price, then switch to the storefront.'}</div><table><thead><tr><th>PRODUCT</th><th>CATEGORY</th><th>PRICE (₹)</th><th>STOCK</th><th></th></tr></thead><tbody>${products.map(p=>`<tr><td>${p.emoji} <b>${escape(p.name)}</b><div class="muted">${escape(p.unit)}</div></td><td>${cats[p.cat][0]}</td><td><input id="price-${p.id}" aria-label="Price for ${escape(p.name)}" type="number" min="1" step="0.01" value="${p.price}"></td><td><input id="stock-${p.id}" aria-label="Stock for ${escape(p.name)}" type="number" min="0" step="1" value="${p.stock}"></td><td><button class="add" data-save="${p.id}">Save</button></td></tr>`).join('')}</tbody></table>`;$$('[data-save]').forEach(b=>b.onclick=async()=>{let p=products.find(x=>x.id===Number(b.dataset.save)),price=Number($('#price-'+p.id).value),stock=Number($('#stock-'+p.id).value);if(!Number.isFinite(price)||price<=0||!Number.isInteger(stock)||stock<0)return notify('Enter a positive price and whole-number stock');if(window.WKCloud){try{b.disabled=true;await window.WKCloud.saveProduct({...p,price,mrp:Math.max(p.mrp,price),stock});notify('Saved to Firebase')}catch(err){notify(err.message);renderAdmin()}finally{b.disabled=false}return}p.price=price;p.mrp=Math.max(p.mrp,price);p.stock=stock;if(cart[p.id]>stock){cart[p.id]=stock;if(!stock)delete cart[p.id]}persist();render();renderAdmin();notify('Price and stock updated')});renderOrders()}
function renderOrders(){$('#orders').innerHTML=orders.length?orders.map(o=>`<article class="order-card"><select data-order="${o.id}" aria-label="Order status">${['New','Packing','Out for delivery','Delivered'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select><b>${o.id} · ${money(o.total)}</b><p class="form-note">${escape(o.date)} · ${escape(o.name)} · ${escape(o.phone)}</p><p class="form-note">${escape(o.address)} · ${escape(o.pin)}</p><p>${o.items.map(i=>escape(i.name)+' × '+i.qty).join(', ')}</p></article>`).join(''):'<div class="empty">No orders yet. Place a demo order from the storefront to see it here.</div>';$$('[data-order]').forEach(s=>s.onchange=async()=>{if(window.WKCloud){try{await window.WKCloud.setStatus(s.dataset.order,s.value);notify('Order updated')}catch(err){notify(err.message);renderOrders()}return}orders.find(o=>o.id===s.dataset.order).status=s.value;persist();notify('Order status updated')})}
$('#inventorytab').onclick=()=>{$('#inventory').hidden=false;$('#orders').hidden=true;$('#inventorytab').classList.add('selected');$('#orderstab').classList.remove('selected')};$('#orderstab').onclick=()=>{$('#inventory').hidden=true;$('#orders').hidden=false;$('#orderstab').classList.add('selected');$('#inventorytab').classList.remove('selected')};
$('#newproduct').onclick=()=>{showModal(`<h2>Add something good.</h2><form id="productform"><label>Product name<input name="name" required maxlength="100"></label><label>Pack size<input name="unit" required maxlength="30" placeholder="e.g. 500 g"></label><label>Category<select name="cat">${cats.slice(0,6).map((c,i)=>`<option value="${i}">${c[0]}</option>`).join('')}</select></label><label>Price (₹)<input name="price" type="number" min="1" step="0.01" required></label><label>Available stock<input name="stock" type="number" min="0" step="1" required></label><button class="primary wide">Add to storefront</button></form>`);$('#productform').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));const product={id:Date.now(),name:d.name,unit:d.unit,cat:Number(d.cat),price:Number(d.price),mrp:Number(d.price),stock:Number(d.stock),emoji:cats[d.cat][1]};if(window.WKCloud){try{await window.WKCloud.saveProduct(product);$('#modal').close();notify('Product added to Firebase')}catch(err){notify(err.message)}return}products.push(product);persist();render();renderAdmin();$('#modal').close();notify('Product added to your shop')}};
function renderLocation(){$('#location small').textContent='⌖ '+delivery.area+' · '+delivery.pin}$('#location').onclick=()=>{showModal(`<h2>Your neighbourhood.</h2><p class="form-note">Delivery is currently available in Wakad, Pune (411057).</p><form id="locationform"><label>Building or locality<input name="area" required maxlength="80" value="${escape(delivery.area)}"></label><label>PIN code<input name="pin" required pattern="411057" value="${escape(delivery.pin)}" title="Currently serving PIN 411057"></label><button class="primary wide">Save delivery location</button></form>`);$('#locationform').onsubmit=e=>{e.preventDefault();delivery=Object.fromEntries(new FormData(e.target));localStorage.setItem('wk-location',JSON.stringify(delivery));renderLocation();$('#modal').close();notify('Delivery location updated')}};
renderLocation();render();

document.addEventListener('click',event=>{if(event.target.closest('[data-close-dialog]'))document.querySelector('dialog')?.close()});
